{"command": "create", "path": "/root/solve.py", "file_text": "import pandas as pd
from itertools import permutations

df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=8)
df = df.dropna(axis=1, how='all')
df.columns = [str(c).strip() for c in df.columns]
df = df[['Turn number', 'Game number', 'Roll 1', 'Roll 2', 'Roll 3', 'Roll 4', 'Roll 5', 'Roll 6']].dropna()
for c in df.columns:
    df[c] = df[c].astype(int)

CATEGORIES = ['HighOften', 'Summation', 'HighsLows', 'TwoNumbers', 'AllNumbers', 'OrderedSubset4']

def turn_scores(rolls):
    hi = max(rolls); lo = min(rolls)
    counts = {}
    for r in rolls: counts[r] = counts.get(r, 0) + 1
    s = {}
    s['HighOften'] = hi * counts[hi]
    s['Summation'] = sum(rolls)
    s['HighsLows'] = hi * lo * (hi - lo)
    s['TwoNumbers'] = 30 if len(set(rolls)) == 2 else None
    s['AllNumbers'] = 40 if set(rolls) == {1, 2, 3, 4, 5, 6} else None
    found = False
    for i in range(len(rolls) - 3):
        seg = rolls[i:i+4]
        if all(seg[j+1] - seg[j] == 1 for j in range(3)):
            found = True; break
        if all(seg[j+1] - seg[j] == -1 for j in range(3)):
            found = True; break
    s['OrderedSubset4'] = 50 if found else None
    return s

def game_score_two_turns(t1, t2):
    best = -1
    for a, b in permutations(CATEGORIES, 2):
        va = t1[a]; vb = t2[b]
        if va is None or vb is None:
            continue
        tot = va + vb
        if tot > best:
            best = tot
    return best

def single_turn_best(t):
    return max(v for v in t.values() if v is not None)

game_scores_A = {}
game_scores_B = {}
for g, grp in df.groupby('Game number'):
    grp = grp.sort_values('Turn number')
    rolls_list = grp[['Roll 1','Roll 2','Roll 3','Roll 4','Roll 5','Roll 6']].values.tolist()
    turns = [turn_scores(r) for r in rolls_list]
    if len(turns) == 2:
        game_scores_A[g] = game_score_two_turns(turns[0], turns[1])
        game_scores_B[g] = game_score_two_turns(turns[0], turns[1])
    elif len(turns) == 1:
        game_scores_A[g] = single_turn_best(turns[0])
        game_scores_B[g] = None
    else:
        game_scores_A[g] = None
        game_scores_B[g] = None

print("Game 7 score:", game_scores_A[7])
print("Game 8 score (policy A, 1-turn best):", game_scores_A[8])
print("Game 8 score (policy B, drop):", game_scores_B[8])

def match_outcomes(scores):
    p1 = p2 = ties = skipped = 0
    for g_odd in range(1, 3001, 2):
        g_even = g_odd + 1
        s1 = scores.get(g_odd); s2 = scores.get(g_even)
        if s1 is None or s2 is None:
            skipped += 1
            continue
        if s1 > s2: p1 += 1
        elif s2 > s1: p2 += 1
        else: ties += 1
    return p1, p2, ties, skipped

for name, scores in [("A: score only available turns", game_scores_A),
                     ("B: drop match with missing turn", game_scores_B)]:
    p1, p2, ties, sk = match_outcomes(scores)
    print(f"{name}: P1={p1}, P2={p2}, ties={ties}, skipped={sk}, diff={p1-p2}")

p1A, p2A, tiesA, skA = match_outcomes(game_scores_A)
answer = p1A - p2A
print("Final answer:", answer)
with open('/root/answer.txt','w') as f:
    f.write(str(answer))
